import React from "react";
import "./ConfirmModal.css";

/**
 * ConfirmPurchaseModal
 * Props:
 *  - show: boolean
 *  - onConfirm: () => void
 *  - onClose: () => void
 *  - message?: string
 *  - confirmText?: string
 *  - cancelText?: string
 *  - colors?: {
 *      bg?: string,        // nền card modal
 *      text?: string,      // màu chữ
 *      backdrop?: string,  // nền mờ phía sau
 *      accent?: string,    // màu dấu !
 *      ring?: string       // viền tròn dấu !
 *    }
 */
const ConfirmPurchaseModal = ({
  show,
  onConfirm,
  onClose,
  message = "Bạn có chắc chắn muốn mua sản phẩm này?",
  confirmText = "ĐỒNG Ý",
  cancelText = "HỦY BỎ",
  colors = {},
}) => {
  if (!show) return null;

  const theme = {
    bg: "#ffffff",
    text: "#2b2e34",
    backdrop: "rgba(0,0,0,.55)",
    accent: "#e0a85a",
    ring: "#f0d9b6",
    ...colors,
  };

  const handleBackdropClick = (e) => {
    if (e.target.classList.contains("custom-modal-overlay")) onClose?.();
  };

  return (
    <>
      {/* Backdrop riêng cho modal xác nhận */}
      <div
        className="modal-backdrop fade show cm-backdrop"
        style={{ backgroundColor: theme.backdrop, opacity: 1 }}
      />

      {/* Overlay giữ center + gắn biến màu */}
      <div
        className="custom-modal-overlay cm d-flex align-items-center justify-content-center"
        onClick={handleBackdropClick}
        role="dialog"
        aria-modal="true"
        aria-labelledby="cm-title"
        style={{
          "--cm-bg": theme.bg,
          "--cm-text": theme.text,
          "--cm-accent": theme.accent,
          "--cm-ring": theme.ring,
        }}
      >
        <div className="modal-dialog" onClick={(e) => e.stopPropagation()}>
          <div className="modal-content border-0 shadow-lg rounded-3">
            <div className="modal-body text-center p-4 p-md-5">
              <div className="cm-icon-wrap mx-auto mb-3">
                <span className="cm-icon">!</span>
              </div>

              <p id="cm-title" className="cm-message fw-semibold mb-4">
                {message}
              </p>

              <div className="d-flex justify-content-center gap-3">
                <button
                  type="button"
                  className="btn btn-primary px-4"
                  onClick={onConfirm}
                >
                  {confirmText}
                </button>
                <button
                  type="button"
                  className="btn btn-danger px-4"
                  onClick={onClose}
                >
                  {cancelText}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default ConfirmPurchaseModal;
